package com.example.carteirainvestimento.service;
import java.time.OffsetDateTime; import java.time.ZoneOffset;
import com.example.carteirainvestimento.domain.Carteira; import com.example.carteirainvestimento.dto.carteira.CarteiraRequest; import com.example.carteirainvestimento.exception.BusinessRuleException; import com.example.carteirainvestimento.exception.ResourceNotFoundException; import com.example.carteirainvestimento.repository.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class CarteiraService { private final CarteiraRepository carteiras; private final AtivoCarteiraRepository ativos; private final PortfolioSnapshotRepository snapshots; private final com.example.carteirainvestimento.repository.UsuarioRepository usuarios; public CarteiraService(CarteiraRepository c, AtivoCarteiraRepository a){this(c,a,null,null);} public CarteiraService(CarteiraRepository c, AtivoCarteiraRepository a, PortfolioSnapshotRepository s){this(c,a,s,null);} @org.springframework.beans.factory.annotation.Autowired public CarteiraService(CarteiraRepository c, AtivoCarteiraRepository a, PortfolioSnapshotRepository s, com.example.carteirainvestimento.repository.UsuarioRepository u){carteiras=c;ativos=a;snapshots=s;usuarios=u;}
@Transactional public Carteira criar(CarteiraRequest r){Carteira c=new Carteira();c.setNome(r.nome());c.setDescricao(r.descricao());c.setDataCriacao(OffsetDateTime.now(ZoneOffset.UTC));currentUserId().ifPresent(id->{if(usuarios!=null)usuarios.findById(id).ifPresent(c::setUsuario);});return carteiras.save(c);} @Transactional(readOnly=true) public Page<Carteira> listar(Pageable p){var uid=currentUserId();return uid.isPresent()?carteiras.findAllByUsuarioId(uid.get(),p):carteiras.findAll(p);} @Transactional(readOnly=true) public Carteira buscar(Long id){var found=currentUserId().flatMap(uid->carteiras.findByIdAndUsuarioId(id,uid));return found.orElseGet(()->currentUserId().isPresent()?throwNotFound():carteiras.findById(id).orElseThrow(()->new ResourceNotFoundException("Carteira nao encontrada")));} @Transactional public Carteira atualizar(Long id,CarteiraRequest r){Carteira c=buscar(id);c.setNome(r.nome());c.setDescricao(r.descricao());return carteiras.save(c);} @Transactional public void excluir(Long id){if(ativos.existsByCarteiraId(id))throw new BusinessRuleException("Carteira possui posicoes");Carteira carteira=buscar(id);if(snapshots!=null)snapshots.deleteByCarteiraId(id);carteiras.delete(carteira);} private Carteira throwNotFound(){throw new ResourceNotFoundException("Carteira nao encontrada");} private java.util.Optional<Long> currentUserId(){var a=org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication();if(a!=null&&a.isAuthenticated()&&a.getPrincipal() instanceof Long id)return java.util.Optional.of(id);return java.util.Optional.empty();}}
